-- Run once in a Snowsight worksheet as ACCOUNTADMIN (new trial account).
-- Creates a least-privilege service user for the SharkWatch app (key-pair auth, read-only on the roster).
USE ROLE ACCOUNTADMIN;
CREATE WAREHOUSE IF NOT EXISTS SHARKWATCH_WH WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE;
CREATE DATABASE IF NOT EXISTS SHARKWATCH;
CREATE SCHEMA IF NOT EXISTS SHARKWATCH.ROSTER;
CREATE ROLE IF NOT EXISTS SHARKWATCH_APP;
GRANT USAGE ON WAREHOUSE SHARKWATCH_WH TO ROLE SHARKWATCH_APP;
GRANT USAGE ON DATABASE SHARKWATCH TO ROLE SHARKWATCH_APP;
GRANT ALL ON SCHEMA SHARKWATCH.ROSTER TO ROLE SHARKWATCH_APP;
CREATE USER IF NOT EXISTS SHARKWATCH_SVC TYPE = SERVICE DEFAULT_ROLE = SHARKWATCH_APP DEFAULT_WAREHOUSE = SHARKWATCH_WH
  RSA_PUBLIC_KEY = '';
GRANT ROLE SHARKWATCH_APP TO USER SHARKWATCH_SVC;
SELECT CURRENT_ORGANIZATION_NAME() || '-' || CURRENT_ACCOUNT_NAME() AS SNOWFLAKE_ACCOUNT;
